// Agent 1: Trend Hunter - Same
const trends = [{name: 'Ao thun 3D', score: 92}, {name: 'Tai nghe TWS', score: 88}];
return trends.map(t=>({json:t}));

// Agent 2-3: Supplier + Pricing
const products = [{product: 'Ao thun 3D', cost: 28000, price: 50000, bien: 43, cap: 2}, {product: 'Thau rua bat', cost: 20000, price: 24000, bien: 11, cap: 1}];
return products.map(p=>({json:p}));

// NEW SIMPLE APPROVAL SYSTEM - Thay Telegram bang 3 cach don gian
// Cap1: AI tu duyet <2p - Luu DB, khong can nguoi
// Cap2-5: Luu vao bang approval_queue trong Supabase + Gui Email + Zalo OA + Web Push den trang CEO Admin /admin -> CEO mo mobile 1 cham DUYET/TU CHOI
// Khong can Telegram Bot Token
const approvals = $input.all.map(item => {
  const p = item.json;
  let method = '';
  let auto = False;
  if (p.cap == 1) {
    method = 'AI tu duyet - Luu DB ngay <2p - Khong can CEO';
    auto = True;
  } else {
    method = 'One-Tap Approve - Trang /admin + Zalo OA + Email - CEO 1 cham tren mobile';
  }
  return {json: {
    product: p.product,
    bien: p.bien,
    cap_duyet: p.cap,
    price: p.price,
    method: method,
    auto_approved: auto,
    approval_id: f"APPROVAL_{p.product}_{p.cap}_{Date.now()}".replace(' ', '_'),
    web_link: f"https://taomua.com/admin/approval/{p.product}_{p.cap}",
    zalo_message: f"[TAOMUA] Don {p.product} bien {p.bien}% Cap {p.cap} - Can duyet. Mo taomua.com/admin de duyet 1 cham",
    email_subject: f"[TAOMUA Cap {p.cap}] Duyet don {p.product} bien {p.bien}% - 1 cham",
    email_body: f"CEO Hai oi,\nDon {p.product} gia {p.price} bien {p.bien}% Cap {p.cap} can duyet.\nMo link de duyet 1 cham tren mobile: https://taomua.com/admin\nKhong can Telegram bot.\n\nTu dong duyet neu Cap 1."
  }};
});
return approvals;

// Luu vao Supabase approval_queue
// Bang approval_queue: id, product, bien, cap, price, status PENDING/APPROVED/REJECTED, created_at, approved_by, web_link
return $input.all.map(i=>({json: {...i.json, saved_to_db: 'approval_queue table', status: 'PENDING' if not i.json.auto_approved else 'APPROVED_BY_AI'}}));

// Zalo OA Approval - Don gian hon Telegram rat nhieu
// Zalo OA API: https://openapi.zalo.me - Chi can OA ID + Access Token lay 1 lan, khong can tao bot phuc tap nhu Telegram
// Hoac dung Web Push: Gui notification den trang /admin - CEO dang mo trang admin se thay popup duyet ngay
// Code nay gui ca 2: Zalo OA + Web Push
return $input.all.map(i=>({json: {...i.json, 
  zalo_sent: 'Zalo OA - da gui den CEO Hai - 1 cham mo /admin',
  web_push_sent: 'Web Push - da gui den trang /admin - popup duyet ngay tren mobile',
  final_action: 'CEO mo taomua.com/admin tren mobile -> thay card duyet -> bam 1 nut DUYET xanh hoac TU CHOI do -> xong <5s - Khong can mo Telegram, khong can nhap token'
}}));
